head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

// 사전 조건 : showImageTooltip=true + tooltipDisplay=true 그리드의 image 컬럼에
//             0행=유효 이미지 경로, 1행=빈 값(이미지 없음) 을 배치한다.
scwin.onpageload = function () {
    // 데이터는 dataList 정적 데이터로 세팅됨(추가 처리 없음)
};

// 특정 행의 image 셀 img 요소를 조회
scwin.getImgEl = function (rowIndex) {
    var gid = target1.id;
    var imgList = document.querySelectorAll("td[id*='" + gid + "_cell_" + rowIndex + "_'] img");
    return imgList.length > 0 ? imgList[imgList.length - 1] : null;
};

// [재현 버튼] 각 image 셀에 마우스 오버 시 표시되는 툴팁 내용(셀 img.src)을 출력
scwin.btn_showTooltip_onclick = function () {
    var img0 = scwin.getImgEl(0);
    var img1 = scwin.getImgEl(1);

    // 유효 이미지 경로 셀(정상) : 마우스 오버 시 이미지 경로가 툴팁으로 표시됨
    if (img0) {
        var attr0 = img0.getAttribute("src");
        scwin.setReturnValue("[유효 이미지 셀] 마우스 오버 툴팁 내용(img.src) : " + img0.src);
        scwin.setReturnValue("    [기대] 이미지 경로가 툴팁으로 표시   [실제] " + attr0);
    } else {
        scwin.setReturnValue("[유효 이미지 셀] img 요소를 찾을 수 없습니다.");
    }

    // 빈 값(이미지 없음) 셀(결함) : 이미지가 없으므로 툴팁이 표시되지 않아야 하나,
    // 툴팁이 표시되며 그 내용이 페이지 URL 로 노출됨
    if (img1) {
        var attr1 = img1.getAttribute("src");
        scwin.setReturnValue("[빈 값 이미지 셀] 마우스 오버 툴팁 내용(img.src) : " + img1.src);
        scwin.setReturnValue("    [기대] 이미지 없음 => 툴팁 미표시   [실제] 툴팁 표시 + 페이지 URL 노출 (getAttribute src = '" + attr1 + "')");
    } else {
        scwin.setReturnValue("[빈 값 이미지 셀] img 요소를 찾을 수 없습니다.");
    }
};
